-- =====================================================================
-- PCL Porsche Company Lens - 13_powerbi_export.sql   (Phase 6)
-- Exports the Power BI star schema from the approved SQL mart.
-- NOTHING is recalculated here: every value is a column of an approved mart view or core table.
-- Only reshaping (join on period_code, unpivot to long form) is done.
-- Run from the pcl_powerbi folder:  psql -d porsche_lens -f ../pcl_sql/13_powerbi_export.sql
-- Output: data/*.csv (UTF-8, comma, header, '.' decimal separator)
-- =====================================================================
\set ON_ERROR_STOP on

-- ---------------------------------------------------------------- DimPeriod
\copy (SELECT p.period_code, p.period_label, p.sort_key, p.fiscal_year, p.half_no, 'H' || p.half_no AS half_label, CASE WHEN pr.period_code IS NOT NULL THEN pr.period_code END AS prior_same_half_code, (pr.period_code IS NOT NULL)::text AS has_prior_in_window, (p.period_code = (SELECT max(period_code) FROM mart.v_panel_hy))::text AS is_latest, v.n_fact_values, v.n_derived_values, coalesce(v.derived_var_ids, '') AS derived_var_ids, CASE WHEN p.half_no = 2 THEN 'H2 = FY - H1 (DERIVED for flow variables)' ELSE 'Published half-year' END AS period_basis FROM core.dim_period p JOIN mart.v_panel_hy v USING (period_code) LEFT JOIN core.dim_period pr ON pr.half_no = p.half_no AND pr.fiscal_year = p.fiscal_year - 1 AND pr.is_half_year AND pr.in_analysis_window ORDER BY p.sort_key) TO 'data/DimPeriod.csv' WITH (FORMAT csv, HEADER)

-- ---------------------------------------------------------------- FactHalfYear (one row per half-year; base values + SQL-derived decompositions)
\copy (SELECT v.period_code, v.grp_revenue, v.grp_ebit, a.adj_realignment_net, a.adj_us_tariffs, a.rounding_band_eur_m, a.assumptions_used AS ebit_assumptions_used, v.exc_battery_memo, v.auto_revenue, v.auto_ebit, v.auto_ebitda, v.auto_ebitda_margin_published, v.rd_total, v.rd_capitalised, v.rd_expensed, v.amort_capitalised_rd, v.rd_cap_rate_published, r.ebit_effect_of_cap_rate_change AS sql_ebit_effect_of_cap_rate_change, r.rd_pl_at_prior_cap_rate AS sql_rd_pl_at_prior_cap_rate, v.capex, v.dep_on_capex, v.da_total, d.impairment_used, d.impairment_status, v.fs_revenue, v.fs_ebit, v.auto_cfo, v.auto_cfi_operating, v.auto_net_cash_flow, v.auto_net_liquidity, c.cash_notes, v.deliveries, v.vehicle_sales, v.asp_published_eur_k, v.bev_share_published, s.volume_effect AS sql_volume_effect, s.asp_effect AS sql_asp_effect, v.bridge_gross_margin_ex_rd, v.bridge_rd, v.bridge_sga, v.bridge_other, v.bridge_extraordinary_memo FROM mart.v_panel_hy v JOIN mart.v_ebit_adjusted a USING (period_code) JOIN mart.v_rd_capitalisation r USING (period_code) JOIN mart.v_da_clean d USING (period_code) JOIN mart.v_asp_volume s USING (period_code) JOIN mart.v_cash_crosscheck c USING (period_code) ORDER BY v.sort_key) TO 'data/FactHalfYear.csv' WITH (FORMAT csv, HEADER)

-- ---------------------------------------------------------------- FactBridgeYoY (long; SQL own decomposition, same half of prior year)
\copy (SELECT b.period_code, b.prior_period_code, x.step_id, x.eur_m, x.pp FROM mart.v_ebit_bridge_yoy b CROSS JOIN LATERAL (VALUES ('S0_START', b.ebit_prior, NULL::numeric), ('S1_EXC', b.eff_exceptional_items, b.pp_exceptional_items), ('S2_TAR', b.eff_us_tariffs, b.pp_us_tariffs), ('S3_CAPDEV', b.eff_rd_capitalisation, b.pp_rd_capitalisation), ('S4_DA', b.eff_clean_da, b.pp_clean_da), ('S5_FS', b.eff_financial_services, b.pp_financial_services), ('S6_RES', b.eff_residual_other_drivers, b.pp_residual_other_drivers), ('S7_DENOM', NULL::numeric, b.pp_revenue_denominator)) AS x(step_id, eur_m, pp) ORDER BY b.sort_key, x.step_id) TO 'data/FactBridgeYoY.csv' WITH (FORMAT csv, HEADER)

-- ---------------------------------------------------------------- FactSensitivity (assumption-driven alternatives; never headline)
\copy (SELECT period_code, 'SENS_A04_RES' AS sensitivity_id, 'Residual / other EBIT drivers if the H1 2026 impairments (EUR 61m) are NOT inside D&A' AS description, 'A-04' AS assumption_id, eff_residual_other_drivers_alt_a04 AS value_eur_m FROM mart.v_ebit_bridge_yoy WHERE eff_residual_other_drivers_alt_a04 IS NOT NULL UNION ALL SELECT period_code, 'SENS_A04_L3', 'L3 hybrid sensitivity if the H1 2026 impairments are NOT inside D&A', 'A-04', ebit_l3_hybrid_alt_a04 FROM mart.v_ebit_adjusted WHERE ebit_l3_hybrid_alt_a04 IS NOT NULL ORDER BY 1, 2) TO 'data/FactSensitivity.csv' WITH (FORMAT csv, HEADER)

-- ---------------------------------------------------------------- FactDeliveryMix
\copy (SELECT period_code, dimension, member_id, member_name, deliveries, share_pct, value_label, CASE dimension WHEN 'model' THEN (SELECT sort_order FROM core.dim_model m WHERE m.model_id = member_id) ELSE (SELECT sort_order FROM core.dim_region r WHERE r.region_id = member_id) END AS member_sort FROM mart.v_delivery_mix ORDER BY sort_key, dimension, member_sort) TO 'data/FactDeliveryMix.csv' WITH (FORMAT csv, HEADER)

-- ---------------------------------------------------------------- Guidance (scenario combinations - NOT forecasts)
\copy (SELECT scenario_id, scenario_type, case_rev, case_ros, case_ex, CASE case_rev WHEN 'low' THEN 1 WHEN 'mid' THEN 2 ELSE 3 END AS sort_rev, CASE case_ros WHEN 'low' THEN 1 WHEN 'mid' THEN 2 ELSE 3 END AS sort_ros, CASE case_ex WHEN 'low' THEN 1 WHEN 'mid' THEN 2 ELSE 3 END AS sort_ex, fy_rev, fy_ros, fy_exc, fy_ebit, h1_rev, h1_ebit, h2_rev, h2_ebit_l0, h2_margin_l0_pct, h2_exceptional_implied, h2_ebit_l1, h2_margin_l1_pct, h2_tariffs_assumed, h2_margin_l2_pct, assumptions_used FROM mart.v_guidance_2026 ORDER BY 6, 7, 8) TO 'data/FactGuidance.csv' WITH (FORMAT csv, HEADER)
\copy (SELECT scenario_id, scenario_type, case_rev, case_m, fy_grp_rev, auto_share_pct_assumed, fy_auto_rev, h2_auto_rev, fy_ebitda_margin, h2_auto_ebitda_margin_pct, fy_ncf_margin, h2_auto_ncf_margin_pct, h1_2026_auto_ebitda_margin_pct, h1_2026_auto_ncf_margin_pct, assumptions_used FROM mart.v_guidance_2026_auto ORDER BY 1) TO 'data/FactGuidanceAuto.csv' WITH (FORMAT csv, HEADER)
\copy (SELECT guidance_id, metric, fiscal_year, low_value, (low_value + high_value) / 2 AS mid_value, high_value, unit_std, basis, value_label, source_id, source_ref FROM core.fact_guidance ORDER BY guidance_id) TO 'data/GuidanceInputs.csv' WITH (FORMAT csv, HEADER)

-- ---------------------------------------------------------------- Lineage and audit tables
\copy (SELECT f.period_code, f.var_id, v.var_name, v.var_group, f.value, f.unit_std, f.value_label, f.origin, coalesce(f.source_id, 'SQL derived') AS source_id, f.source_ref, f.rounding FROM core.fact_financial f JOIN core.dim_variable v USING (var_id) JOIN core.dim_period p USING (period_code) WHERE p.is_half_year AND p.in_analysis_window ORDER BY p.sort_key, f.var_id) TO 'data/FactLineage.csv' WITH (FORMAT csv, HEADER)
\copy (SELECT source_id, tier, publisher, document_title, doc_type, reporting_period, publication_date, url FROM audit.dim_source ORDER BY source_id) TO 'data/DimSource.csv' WITH (FORMAT csv, HEADER)
\copy (SELECT assumption_id, statement, applies_to, rationale, sensitivity FROM mart.assumption ORDER BY assumption_id) TO 'data/Assumption.csv' WITH (FORMAT csv, HEADER)
\copy (SELECT period_code, topic, note, source_id, source_ref FROM mart.annotation ORDER BY period_code, topic) TO 'data/Annotation.csv' WITH (FORMAT csv, HEADER)

-- ---------------------------------------------------------------- RefSQL: reference values for the in-Power BI QA page
-- (metric_key, period_code or scenario, value exactly as published by the mart view, tolerance = view rounding)
\copy (SELECT metric_key, period_code, scenario_id, sql_value, tolerance, sql_view, dimension, member_id FROM (SELECT q.*, NULL::text AS dimension, NULL::text AS member_id FROM (SELECT x.metric_key, a.period_code, NULL::text AS scenario_id, x.sql_value, x.tolerance, 'mart.v_ebit_adjusted' AS sql_view FROM mart.v_ebit_adjusted a CROSS JOIN LATERAL (VALUES ('ebit_l0_reported', a.ebit_l0_reported, 0.000001), ('ebit_l1_ex_realignment', a.ebit_l1_ex_realignment, 0.000001), ('ebit_l2_ex_realignment_tariffs', a.ebit_l2_ex_realignment_tariffs, 0.000001), ('ebit_l3_hybrid_sensitivity', a.ebit_l3_hybrid_sensitivity, 0.000001), ('margin_l0_reported_pct', a.margin_l0_reported_pct, 0.005), ('margin_l1_pct', a.margin_l1_pct, 0.005), ('margin_l2_pct', a.margin_l2_pct, 0.005), ('margin_l3_hybrid_pct', a.margin_l3_hybrid_pct, 0.005), ('yoy_ebit_l1', a.yoy_ebit_l1, 0.000001), ('yoy_margin_l1_pp', a.yoy_margin_l1_pp, 0.011), ('yoy_margin_l0_pp', a.yoy_margin_l0_pp, 0.011)) AS x(metric_key, sql_value, tolerance) UNION ALL SELECT x.metric_key, d.period_code, NULL, x.sql_value, x.tolerance, 'mart.v_da_clean' FROM mart.v_da_clean d CROSS JOIN LATERAL (VALUES ('da_clean', d.da_clean, 0.000001), ('yoy_da_clean', d.yoy_da_clean, 0.000001)) AS x(metric_key, sql_value, tolerance) UNION ALL SELECT x.metric_key, r.period_code, NULL, x.sql_value, x.tolerance, 'mart.v_rd_capitalisation' FROM mart.v_rd_capitalisation r CROSS JOIN LATERAL (VALUES ('rd_total_costs', r.rd_total_costs, 0.000001), ('rd_pl_charge', r.rd_pl_charge, 0.000001), ('cap_rate_calc_pct', r.cap_rate_calc_pct, 0.05), ('net_capitalisation', r.net_capitalisation, 0.000001), ('ebit_effect_of_cap_rate_change', r.ebit_effect_of_cap_rate_change, 0.05), ('yoy_rd_pl_charge', r.yoy_rd_pl_charge, 0.000001)) AS x(metric_key, sql_value, tolerance) UNION ALL SELECT x.metric_key, s.period_code, NULL, x.sql_value, x.tolerance, 'mart.v_asp_volume' FROM mart.v_asp_volume s CROSS JOIN LATERAL (VALUES ('asp_calc_eur_k', s.asp_calc_eur_k, 0.005), ('yoy_vehicle_sales_pct', s.yoy_vehicle_sales_pct, 0.05), ('yoy_asp_pct', s.yoy_asp_pct, 0.051), ('yoy_auto_revenue', s.yoy_auto_revenue, 0.000001), ('volume_effect', s.volume_effect, 0.05), ('asp_effect', s.asp_effect, 0.05)) AS x(metric_key, sql_value, tolerance) UNION ALL SELECT x.metric_key, c.period_code, NULL, x.sql_value, x.tolerance, 'mart.v_cash_crosscheck' FROM mart.v_cash_crosscheck c CROSS JOIN LATERAL (VALUES ('auto_net_cash_flow', c.auto_net_cash_flow, 0.000001), ('ncf_margin_pct', c.ncf_margin_pct, 0.005), ('ebitda_margin_calc_pct', c.ebitda_margin_calc_pct, 0.005), ('cfo_to_ebitda', c.cfo_to_ebitda, 0.005), ('simple_cash_proxy', c.simple_cash_proxy, 0.000001)) AS x(metric_key, sql_value, tolerance) UNION ALL SELECT x.metric_key, b.period_code, NULL, x.sql_value, x.tolerance, 'mart.v_ebit_bridge_yoy' FROM mart.v_ebit_bridge_yoy b CROSS JOIN LATERAL (VALUES ('d_ebit', b.d_ebit, 0.000001), ('eff_residual_other_drivers', b.eff_residual_other_drivers, 0.000001), ('d_margin_pp', b.d_margin_pp, 0.0005)) AS x(metric_key, sql_value, tolerance) UNION ALL SELECT x.metric_key, 'ALL', g.scenario_id, x.sql_value, x.tolerance, 'mart.v_guidance_2026' FROM mart.v_guidance_2026 g CROSS JOIN LATERAL (VALUES ('g_h2_margin_l0_pct', g.h2_margin_l0_pct, 0.005), ('g_h2_margin_l1_pct', g.h2_margin_l1_pct, 0.005), ('g_h2_margin_l2_pct', g.h2_margin_l2_pct, 0.005)) AS x(metric_key, sql_value, tolerance) UNION ALL SELECT x.metric_key, 'ALL', NULL, x.sql_value, x.tolerance, 'mart.v_guidance_2026_summary' FROM mart.v_guidance_2026_summary s CROSS JOIN LATERAL (VALUES ('gs_l0_min', s.h2_margin_l0_min, 0.005), ('gs_l0_mid', s.h2_margin_l0_mid, 0.005), ('gs_l0_max', s.h2_margin_l0_max, 0.005), ('gs_l1_min', s.h2_margin_l1_min, 0.005), ('gs_l1_mid', s.h2_margin_l1_mid, 0.005), ('gs_l1_max', s.h2_margin_l1_max, 0.005), ('gs_l2_min', s.h2_margin_l2_min, 0.005), ('gs_l2_mid', s.h2_margin_l2_mid, 0.005), ('gs_l2_max', s.h2_margin_l2_max, 0.005)) AS x(metric_key, sql_value, tolerance) UNION ALL SELECT x.metric_key, 'ALL', g.scenario_id, x.sql_value, x.tolerance, 'mart.v_guidance_2026_auto' FROM mart.v_guidance_2026_auto g CROSS JOIN LATERAL (VALUES ('ga_h2_ebitda_margin_pct', g.h2_auto_ebitda_margin_pct, 0.005), ('ga_h2_ncf_margin_pct', g.h2_auto_ncf_margin_pct, 0.005)) AS x(metric_key, sql_value, tolerance)) q WHERE sql_value IS NOT NULL UNION ALL SELECT 'mix_share_pct', period_code, NULL, share_pct, 0.005, 'mart.v_delivery_mix', dimension, member_id FROM mart.v_delivery_mix) r ORDER BY sql_view, metric_key, period_code, scenario_id, dimension, member_id) TO 'data/RefSQL.csv' WITH (FORMAT csv, HEADER)
